contracts/AchievementSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title AchievementSystem
 * @notice NFT-based achievement system for milestone tracking
 * @dev Mints NFT achievements for user milestones and accomplishments
 */
contract AchievementSystem is ERC721, Ownable, Pausable, ReentrancyGuard {

    uint256 public nextTokenId = 1;
    string public baseURI;

    // Achievement categories
    enum AchievementCategory {
        PREDICTION_ACCURACY,  // High accuracy predictions
        WIN_STREAK,          // Consecutive wins
        TOTAL_VOLUME,        // Trading volume milestones
        REFERRAL,            // Referral achievements
        TOURNAMENT,          // Tournament wins
        SPECIAL_EVENT        // Special platform events
    }

    struct Achievement {
        uint256 tokenId;
        AchievementCategory category;
        string name;
        string description;
        uint256 requirement; // Required value for achievement
        bool active;
        uint256 mintedCount;
    }

    mapping(uint256 => Achievement) public achievements;
    mapping(address => mapping(AchievementCategory => uint256)) public userProgress;
    mapping(address => mapping(uint256 => bool)) public userAchievements;

    uint256 public totalAchievements;
    uint256 public totalMinted;

    event AchievementCreated(
        uint256 indexed achievementId,
        AchievementCategory category,
        string name,
        uint256 requirement
    );

    event AchievementMinted(
        address indexed user,
        uint256 indexed tokenId,
        uint256 indexed achievementId,
        AchievementCategory category
    );

    event ProgressUpdated(
        address indexed user,
        AchievementCategory category,
        uint256 newProgress
    );

    event BaseURIUpdated(string oldBaseURI, string newBaseURI);

    constructor(
        string memory name,
        string memory symbol,
        string memory baseURI_
    ) ERC721(name, symbol) Ownable(msg.sender) {
        baseURI = baseURI_;
    }

    /**
     * @notice Create a new achievement
     * @param category Achievement category
     * @param name Achievement name
     * @param description Achievement description
     * @param requirement Required value to unlock achievement
     */
    function createAchievement(
        AchievementCategory category,
        string memory name,
        string memory description,
        uint256 requirement
    ) external onlyOwner returns (uint256) {
        uint256 achievementId = totalAchievements + 1;

        achievements[achievementId] = Achievement({
            tokenId: nextTokenId,
            category: category,
            name: name,
            description: description,
            requirement: requirement,
            active: true,
            mintedCount: 0
        });

        totalAchievements = achievementId;
        nextTokenId++;

        emit AchievementCreated(achievementId, category, name, requirement);

        return achievementId;
    }

    /**
     * @notice Mint achievement NFT for user
     * @param user User address to mint achievement for
     * @param achievementId Achievement ID to mint
     */
    function mintAchievement(
        address user,
        uint256 achievementId
    ) external onlyOwner nonReentrant returns (uint256) {
        require(achievements[achievementId].active, "Achievement not active");
        require(!userAchievements[user][achievementId], "Achievement already owned");
        require(userProgress[user][achievements[achievementId].category] >= achievements[achievementId].requirement, "Requirement not met");

        uint256 tokenId = achievements[achievementId].tokenId + achievements[achievementId].mintedCount;

        _safeMint(user, tokenId);

        userAchievements[user][achievementId] = true;
        achievements[achievementId].mintedCount++;
        totalMinted++;

        emit AchievementMinted(user, tokenId, achievementId, achievements[achievementId].category);

        return tokenId;
    }

    /**
     * @notice Update user progress for a category
     * @param user User address
     * @param category Achievement category
     * @param progress New progress value
     */
    function updateProgress(
        address user,
        AchievementCategory category,
        uint256 progress
    ) external onlyOwner {
        userProgress[user][category] = progress;
        emit ProgressUpdated(user, category, progress);
    }

    /**
     * @notice Batch update user progress
     * @param users Array of user addresses
     * @param categories Array of achievement categories
     * @param progresses Array of progress values
     */
    function batchUpdateProgress(
        address[] calldata users,
        AchievementCategory[] calldata categories,
        uint256[] calldata progresses
    ) external onlyOwner {
        require(users.length == categories.length && categories.length == progresses.length, "Array length mismatch");

        for (uint256 i = 0; i < users.length; i++) {
            userProgress[users[i]][categories[i]] = progresses[i];
            emit ProgressUpdated(users[i], categories[i], progresses[i]);
        }
    }

    /**
     * @notice Update base URI for NFT metadata
     * @param newBaseURI New base URI
     */
    function setBaseURI(string memory newBaseURI) external onlyOwner {
        string memory oldBaseURI = baseURI;
        baseURI = newBaseURI;
        emit BaseURIUpdated(oldBaseURI, newBaseURI);
    }

    /**
     * @notice Deactivate an achievement
     * @param achievementId Achievement ID to deactivate
     */
    function deactivateAchievement(uint256 achievementId) external onlyOwner {
        achievements[achievementId].active = false;
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get user's progress for all categories
     * @param user User address
     */
    function getUserProgress(address user) external view returns (
        uint256 predictionAccuracy,
        uint256 winStreak,
        uint256 totalVolume,
        uint256 referral,
        uint256 tournament,
        uint256 specialEvent
    ) {
        return (
            userProgress[user][AchievementCategory.PREDICTION_ACCURACY],
            userProgress[user][AchievementCategory.WIN_STREAK],
            userProgress[user][AchievementCategory.TOTAL_VOLUME],
            userProgress[user][AchievementCategory.REFERRAL],
            userProgress[user][AchievementCategory.TOURNAMENT],
            userProgress[user][AchievementCategory.SPECIAL_EVENT]
        );
    }

    /**
     * @notice Check if user owns a specific achievement
     * @param user User address
     * @param achievementId Achievement ID
     */
    function hasAchievement(address user, uint256 achievementId) external view returns (bool) {
        return userAchievements[user][achievementId];
    }

    /**
     * @notice Get achievement info
     * @param achievementId Achievement ID
     */
    function getAchievement(uint256 achievementId) external view returns (
        uint256 tokenId,
        AchievementCategory category,
        string memory name,
        string memory description,
        uint256 requirement,
        bool active,
        uint256 mintedCount
    ) {
        Achievement memory achievement = achievements[achievementId];
        return (
            achievement.tokenId,
            achievement.category,
            achievement.name,
            achievement.description,
            achievement.requirement,
            achievement.active,
            achievement.mintedCount
        );
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalAchievements,
        uint256 _totalMinted,
        uint256 _nextTokenId
    ) {
        return (totalAchievements, totalMinted, nextTokenId);
    }

    /**
     * @notice Override _baseURI to return the base URI
     */
    function _baseURI() internal view override returns (string memory) {
        return baseURI;
    }

    /**
     * @notice Override _update to add pausable functionality
     */
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override whenNotPaused returns (address) {
        return super._update(to, tokenId, auth);
    }
}

contracts/MultiTokenVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MultiTokenVault
 * @dev Manages multi-token deposits and withdrawals for NECTIQ platform on Polygon Amoy
 * @notice Supports POL (native), WETH, USDC, LINK, and NTIQ tokens
 * @author NECTIQ Team
 */
contract MultiTokenVault is ReentrancyGuard, Ownable, Pausable {
    using SafeERC20 for IERC20;

    // ============ STATE VARIABLES ============

    /// @notice Mapping of user addresses to token addresses to their balances
    mapping(address => mapping(address => uint256)) public userBalances;

    /// @notice Total deposits per token
    mapping(address => uint256) public totalDeposits;

    /// @notice Supported tokens (address(0) = native POL)
    mapping(address => bool) public supportedTokens;

    /// @notice Token addresses
    address public constant NATIVE_TOKEN = address(0); // POL
    address public immutable WETH;
    address public immutable USDC;
    address public immutable LINK;
    address public immutable NTIQ;

    /// @notice Minimum deposit amounts per token (in token's decimals)
    mapping(address => uint256) public minDeposit;

    /// @notice Maximum deposit amounts per token (in token's decimals)
    mapping(address => uint256) public maxDeposit;

    /// @notice Backend signer address for withdrawal authorization
    address public backendSigner;

    /// @notice Nonce for preventing replay attacks
    mapping(address => uint256) public withdrawalNonces;

    // ============ EVENTS ============

    /// @notice Emitted when a user deposits tokens
    event Deposit(
        address indexed user,
        address indexed token,
        uint256 amount,
        uint256 timestamp,
        uint256 newBalance
    );

    /// @notice Emitted when a user withdraws tokens
    event Withdrawal(
        address indexed user,
        address indexed token,
        uint256 amount,
        uint256 timestamp,
        uint256 newBalance,
        uint256 nonce
    );

    /// @notice Emitted when backend signer is updated
    event BackendSignerUpdated(
        address indexed oldSigner,
        address indexed newSigner
    );

    /// @notice Emitted when a token is added/removed from supported list
    event TokenSupportUpdated(
        address indexed token,
        bool supported
    );

    /// @notice Emitted when deposit limits are updated
    event DepositLimitsUpdated(
        address indexed token,
        uint256 minDeposit,
        uint256 maxDeposit
    );

    // ============ ERRORS ============

    error InvalidAmount();
    error InsufficientBalance();
    error TransferFailed();
    error InvalidSignature();
    error NonceAlreadyUsed();
    error ZeroAddress();
    error TokenNotSupported();
    error InvalidToken();

    // ============ CONSTRUCTOR ============

    /**
     * @notice Initialize the vault with token addresses and backend signer
     * @param _backendSigner Address authorized to sign withdrawal requests
     * @param _weth WETH token address on Polygon Amoy
     * @param _usdc USDC token address on Polygon Amoy
     * @param _link LINK token address on Polygon Amoy
     * @param _ntiq NTIQ token address
     */
    constructor(
        address _backendSigner,
        address _weth,
        address _usdc,
        address _link,
        address _ntiq
    ) Ownable(msg.sender) {
        if (_backendSigner == address(0)) revert ZeroAddress();
        if (_weth == address(0) || _usdc == address(0) || _link == address(0) || _ntiq == address(0)) {
            revert InvalidToken();
        }

        backendSigner = _backendSigner;
        WETH = _weth;
        USDC = _usdc;
        LINK = _link;
        NTIQ = _ntiq;

        // Enable supported tokens
        supportedTokens[NATIVE_TOKEN] = true; // POL
        supportedTokens[_weth] = true;
        supportedTokens[_usdc] = true;
        supportedTokens[_link] = true;
        supportedTokens[_ntiq] = true;

        // Set default deposit limits for POL (18 decimals)
        minDeposit[NATIVE_TOKEN] = 0.01 ether; // 0.01 POL
        maxDeposit[NATIVE_TOKEN] = 1000 ether; // 1000 POL

        // Set default deposit limits for WETH (18 decimals)
        minDeposit[_weth] = 0.001 ether; // 0.001 WETH
        maxDeposit[_weth] = 10 ether; // 10 WETH

        // Set default deposit limits for USDC (6 decimals)
        minDeposit[_usdc] = 1 * 10**6; // 1 USDC
        maxDeposit[_usdc] = 10000 * 10**6; // 10,000 USDC

        // Set default deposit limits for LINK (18 decimals)
        minDeposit[_link] = 0.1 ether; // 0.1 LINK
        maxDeposit[_link] = 1000 ether; // 1000 LINK

        // Set default deposit limits for NTIQ (18 decimals)
        minDeposit[_ntiq] = 50 * 10**18; // 50 NTIQ
        maxDeposit[_ntiq] = 10000000 * 10**18; // 10M NTIQ
    }

    // ============ DEPOSIT FUNCTIONS ============

    /**
     * @notice Deposit native POL to user's account
     * @dev Requires msg.value to be within MIN and MAX limits
     */
    function depositPOL() external payable nonReentrant whenNotPaused {
        if (msg.value < minDeposit[NATIVE_TOKEN] || msg.value > maxDeposit[NATIVE_TOKEN]) {
            revert InvalidAmount();
        }

        // Update balances
        userBalances[msg.sender][NATIVE_TOKEN] += msg.value;
        totalDeposits[NATIVE_TOKEN] += msg.value;

        emit Deposit(
            msg.sender,
            NATIVE_TOKEN,
            msg.value,
            block.timestamp,
            userBalances[msg.sender][NATIVE_TOKEN]
        );
    }

    /**
     * @notice Deposit ERC20 tokens to user's account
     * @param token Address of the token to deposit (WETH, USDC, or LINK)
     * @param amount Amount of tokens to deposit (in token's decimals)
     */
    function depositToken(
        address token,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        if (!supportedTokens[token] || token == NATIVE_TOKEN) {
            revert TokenNotSupported();
        }

        if (amount < minDeposit[token] || amount > maxDeposit[token]) {
            revert InvalidAmount();
        }

        // Transfer tokens from user to vault
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        // Update balances
        userBalances[msg.sender][token] += amount;
        totalDeposits[token] += amount;

        emit Deposit(
            msg.sender,
            token,
            amount,
            block.timestamp,
            userBalances[msg.sender][token]
        );
    }

    // ============ WITHDRAWAL FUNCTIONS ============

    /**
     * @notice Withdraw native POL from user's account
     * @param amount Amount of POL to withdraw (in wei)
     * @param nonce Unique nonce for this withdrawal
     * @param signature Backend signature authorizing this withdrawal
     */
    function withdrawPOL(
        uint256 amount,
        uint256 nonce,
        bytes memory signature
    ) external nonReentrant whenNotPaused {
        // Verify signature
        if (!_verifyWithdrawalSignature(msg.sender, NATIVE_TOKEN, amount, nonce, signature)) {
            revert InvalidSignature();
        }

        // Check nonce hasn't been used
        if (withdrawalNonces[msg.sender] >= nonce) {
            revert NonceAlreadyUsed();
        }

        // Check balance
        if (userBalances[msg.sender][NATIVE_TOKEN] < amount) {
            revert InsufficientBalance();
        }

        // Update nonce
        withdrawalNonces[msg.sender] = nonce;

        // Update balances
        userBalances[msg.sender][NATIVE_TOKEN] -= amount;
        totalDeposits[NATIVE_TOKEN] -= amount;

        // Transfer POL to user
        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawal(
            msg.sender,
            NATIVE_TOKEN,
            amount,
            block.timestamp,
            userBalances[msg.sender][NATIVE_TOKEN],
            nonce
        );
    }

    /**
     * @notice Withdraw ERC20 tokens from user's account
     * @param token Address of the token to withdraw (WETH, USDC, or LINK)
     * @param amount Amount of tokens to withdraw (in token's decimals)
     * @param nonce Unique nonce for this withdrawal
     * @param signature Backend signature authorizing this withdrawal
     */
    function withdrawToken(
        address token,
        uint256 amount,
        uint256 nonce,
        bytes memory signature
    ) external nonReentrant whenNotPaused {
        if (!supportedTokens[token] || token == NATIVE_TOKEN) {
            revert TokenNotSupported();
        }

        // Verify signature
        if (!_verifyWithdrawalSignature(msg.sender, token, amount, nonce, signature)) {
            revert InvalidSignature();
        }

        // Check nonce hasn't been used
        if (withdrawalNonces[msg.sender] >= nonce) {
            revert NonceAlreadyUsed();
        }

        // Check balance
        if (userBalances[msg.sender][token] < amount) {
            revert InsufficientBalance();
        }

        // Update nonce
        withdrawalNonces[msg.sender] = nonce;

        // Update balances
        userBalances[msg.sender][token] -= amount;
        totalDeposits[token] -= amount;

        // Transfer tokens to user
        IERC20(token).safeTransfer(msg.sender, amount);

        emit Withdrawal(
            msg.sender,
            token,
            amount,
            block.timestamp,
            userBalances[msg.sender][token],
            nonce
        );
    }

    // ============ INTERNAL FUNCTIONS ============

    /**
     * @notice Verify withdrawal signature from backend
     * @param user User address requesting withdrawal
     * @param token Token address
     * @param amount Withdrawal amount
     * @param nonce Withdrawal nonce
     * @param signature Backend signature
     * @return bool True if signature is valid
     */
    function _verifyWithdrawalSignature(
        address user,
        address token,
        uint256 amount,
        uint256 nonce,
        bytes memory signature
    ) internal view returns (bool) {
        bytes32 messageHash = keccak256(
            abi.encodePacked(user, token, amount, nonce, address(this))
        );
        bytes32 ethSignedMessageHash = _getEthSignedMessageHash(messageHash);

        return _recoverSigner(ethSignedMessageHash, signature) == backendSigner;
    }

    /**
     * @notice Get Ethereum signed message hash
     */
    function _getEthSignedMessageHash(bytes32 messageHash) internal pure returns (bytes32) {
        return keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );
    }

    /**
     * @notice Recover signer address from signature
     */
    function _recoverSigner(
        bytes32 ethSignedMessageHash,
        bytes memory signature
    ) internal pure returns (address) {
        (bytes32 r, bytes32 s, uint8 v) = _splitSignature(signature);
        return ecrecover(ethSignedMessageHash, v, r, s);
    }

    /**
     * @notice Split signature into r, s, v components
     */
    function _splitSignature(bytes memory sig) internal pure returns (
        bytes32 r,
        bytes32 s,
        uint8 v
    ) {
        require(sig.length == 65, "Invalid signature length");

        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @notice Get user's balance for a specific token
     * @param user User address
     * @param token Token address (address(0) for POL)
     * @return uint256 User's balance
     */
    function getUserBalance(address user, address token) external view returns (uint256) {
        return userBalances[user][token];
    }

    /**
     * @notice Get user's balances for all supported tokens
     * @param user User address
     * @return pol POL balance
     * @return weth WETH balance
     * @return usdc USDC balance
     * @return link LINK balance
     */
    function getUserBalances(address user) external view returns (
        uint256 pol,
        uint256 weth,
        uint256 usdc,
        uint256 link
    ) {
        pol = userBalances[user][NATIVE_TOKEN];
        weth = userBalances[user][WETH];
        usdc = userBalances[user][USDC];
        link = userBalances[user][LINK];
    }

    /**
     * @notice Check if a token is supported
     * @param token Token address to check
     * @return bool True if token is supported
     */
    function isTokenSupported(address token) external view returns (bool) {
        return supportedTokens[token];
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @notice Update backend signer address
     * @param newSigner New backend signer address
     */
    function updateBackendSigner(address newSigner) external onlyOwner {
        if (newSigner == address(0)) revert ZeroAddress();

        address oldSigner = backendSigner;
        backendSigner = newSigner;

        emit BackendSignerUpdated(oldSigner, newSigner);
    }

    /**
     * @notice Update token support status
     * @param token Token address
     * @param supported Whether token is supported
     */
    function updateTokenSupport(address token, bool supported) external onlyOwner {
        supportedTokens[token] = supported;
        emit TokenSupportUpdated(token, supported);
    }

    /**
     * @notice Update deposit limits for a token
     * @param token Token address
     * @param min Minimum deposit amount
     * @param max Maximum deposit amount
     */
    function updateDepositLimits(
        address token,
        uint256 min,
        uint256 max
    ) external onlyOwner {
        if (min >= max) revert InvalidAmount();

        minDeposit[token] = min;
        maxDeposit[token] = max;

        emit DepositLimitsUpdated(token, min, max);
    }

    /**
     * @notice Pause the contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause the contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Emergency withdrawal of POL (owner only)
     * @param amount Amount to withdraw
     */
    function emergencyWithdrawPOL(uint256 amount) external onlyOwner {
        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();
    }

    /**
     * @notice Emergency withdrawal of ERC20 tokens (owner only)
     * @param token Token address
     * @param amount Amount to withdraw
     */
    function emergencyWithdrawToken(address token, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(msg.sender, amount);
    }

    // ============ RECEIVE FUNCTION ============

    /// @notice Allow contract to receive POL directly
    receive() external payable {
        // Direct POL transfers go to contract balance but not credited to users
        // Users must use depositPOL() function for proper accounting
    }
}

contracts/ParlayStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ParlayStaking
 * @notice Multi-prediction staking with compound multiplier rewards
 * @dev 6% platform fee on gross rewards
 */
contract ParlayStaking is ReentrancyGuard, Pausable, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable ntiqToken;
    address public treasury;
    uint256 public constant PLATFORM_FEE_RATE = 600; // 6% = 600 basis points
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MIN_COINS = 2;
    uint256 public constant MAX_COINS = 10;

    // Duration multipliers (basis points)
    uint256 public constant DURATION_1H = 12000; // 1.2x
    uint256 public constant DURATION_6H = 15000; // 1.5x
    uint256 public constant DURATION_24H = 20000; // 2.0x
    uint256 public constant DURATION_7D = 30000; // 3.0x

    struct ParlayStake {
        address user;
        uint256 amount;
        uint8 coinCount;
        uint256 duration; // Duration in seconds (1h, 6h, 24h, 7d)
        uint256 durationMultiplier; // Duration-based multiplier
        uint256 timestamp;
        bool released;
        bool forfeited;
        uint256 rewardAmount;
    }

    mapping(bytes32 => ParlayStake) public parlays;
    mapping(address => uint256) public userTotalStaked;
    uint256 public totalStaked;
    uint256 public totalRewardsDistributed;
    uint256 public totalFeesCollected;

    event ParlayStakeLocked(
        bytes32 indexed parlayId,
        address indexed user,
        uint256 amount,
        uint8 coinCount,
        uint256 timestamp
    );

    event ParlayRewardReleased(
        bytes32 indexed parlayId,
        address indexed user,
        uint256 reward,
        uint256 fee,
        uint256 multiplierBasisPoints
    );

    event ParlayStakeForfeited(
        bytes32 indexed parlayId,
        address indexed user,
        uint256 amount
    );

    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(
        address _ntiqToken,
        address _treasury
    ) Ownable(msg.sender) {
        require(_ntiqToken != address(0), "Invalid NTIQ token address");
        require(_treasury != address(0), "Invalid treasury address");

        ntiqToken = IERC20(_ntiqToken);
        treasury = _treasury;
    }

    /**
     * @notice Lock NTIQ tokens for a parlay
     * @param parlayId Unique identifier for the parlay
     * @param amount Amount of NTIQ to stake
     * @param coinCount Number of predictions in parlay (2-10)
     * @param duration Duration in seconds (3600=1h, 21600=6h, 86400=24h, 604800=7d)
     */
    function lockParlayStake(
        bytes32 parlayId,
        uint256 amount,
        uint8 coinCount,
        uint256 duration
    ) external nonReentrant whenNotPaused returns (bool) {
        require(amount > 0, "Amount must be greater than 0");
        require(coinCount >= MIN_COINS, "Minimum 2 coins required");
        require(coinCount <= MAX_COINS, "Maximum 10 coins allowed");
        require(parlays[parlayId].user == address(0), "Parlay already exists");

        // Validate duration and get multiplier
        uint256 durationMultiplier = _getDurationMultiplier(duration);
        require(durationMultiplier > 0, "Invalid duration");

        // Transfer NTIQ from user to contract
        ntiqToken.safeTransferFrom(msg.sender, address(this), amount);

        // Store parlay info
        parlays[parlayId] = ParlayStake({
            user: msg.sender,
            amount: amount,
            coinCount: coinCount,
            duration: duration,
            durationMultiplier: durationMultiplier,
            timestamp: block.timestamp,
            released: false,
            forfeited: false,
            rewardAmount: 0
        });

        userTotalStaked[msg.sender] += amount;
        totalStaked += amount;

        emit ParlayStakeLocked(parlayId, msg.sender, amount, coinCount, block.timestamp);

        return true;
    }

    /**
     * @notice Release compound reward for winning parlay
     * Formula: (1.5 × durationMultiplier)^coinCount
     * @param parlayId Unique identifier for the parlay
     */
    function releaseCompoundReward(
        bytes32 parlayId
    ) external nonReentrant onlyOwner returns (bool) {
        ParlayStake storage parlay = parlays[parlayId];

        require(parlay.user != address(0), "Parlay not found");
        require(!parlay.released, "Reward already released");
        require(!parlay.forfeited, "Stake already forfeited");

        // Calculate compound reward: (1.5 × durationMultiplier)^coinCount
        uint256 baseMultiplier = (15000 * parlay.durationMultiplier) / BASIS_POINTS; // 1.5 × durationMultiplier
        uint256 compoundMultiplier = _power(baseMultiplier, parlay.coinCount);
        uint256 grossReward = (parlay.amount * compoundMultiplier) / BASIS_POINTS;

        // Apply 6% platform fee
        uint256 platformFee = (grossReward * PLATFORM_FEE_RATE) / BASIS_POINTS;
        uint256 netReward = grossReward - platformFee;

        // Mark as released
        parlay.released = true;
        parlay.rewardAmount = netReward;

        // Transfer reward to user
        ntiqToken.safeTransfer(parlay.user, netReward);

        // Transfer fee to treasury
        ntiqToken.safeTransfer(treasury, platformFee);

        totalRewardsDistributed += netReward;
        totalFeesCollected += platformFee;

        emit ParlayRewardReleased(
            parlayId,
            parlay.user,
            netReward,
            platformFee,
            compoundMultiplier
        );

        return true;
    }

    /**
     * @notice Forfeit stake when any prediction is wrong
     * @param parlayId Unique identifier for the parlay
     */
    function forfeitStake(
        bytes32 parlayId
    ) external nonReentrant onlyOwner returns (bool) {
        ParlayStake storage parlay = parlays[parlayId];

        require(parlay.user != address(0), "Parlay not found");
        require(!parlay.released, "Reward already released");
        require(!parlay.forfeited, "Stake already forfeited");

        // Mark as forfeited
        parlay.forfeited = true;

        // Transfer entire stake to treasury
        ntiqToken.safeTransfer(treasury, parlay.amount);
        totalFeesCollected += parlay.amount;

        emit ParlayStakeForfeited(parlayId, parlay.user, parlay.amount);

        return true;
    }

    /**
     * @notice Update treasury address
     * @param newTreasury New treasury address
     */
    function updateTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Invalid treasury address");
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get parlay info
     * @param parlayId Unique identifier for the parlay
     */
    function getParlay(bytes32 parlayId) external view returns (
        address user,
        uint256 amount,
        uint8 coinCount,
        uint256 duration,
        uint256 durationMultiplier,
        uint256 timestamp,
        bool released,
        bool forfeited,
        uint256 rewardAmount
    ) {
        ParlayStake memory parlay = parlays[parlayId];
        return (
            parlay.user,
            parlay.amount,
            parlay.coinCount,
            parlay.duration,
            parlay.durationMultiplier,
            parlay.timestamp,
            parlay.released,
            parlay.forfeited,
            parlay.rewardAmount
        );
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalStaked,
        uint256 _totalRewardsDistributed,
        uint256 _totalFeesCollected
    ) {
        return (totalStaked, totalRewardsDistributed, totalFeesCollected);
    }

    /**
     * @notice Get duration multiplier for given duration
     * @param duration Duration in seconds
     * @return multiplier Duration multiplier in basis points
     */
    function _getDurationMultiplier(uint256 duration) internal pure returns (uint256 multiplier) {
        if (duration == 3600) { // 1 hour
            return DURATION_1H;
        } else if (duration == 21600) { // 6 hours
            return DURATION_6H;
        } else if (duration == 86400) { // 24 hours
            return DURATION_24H;
        } else if (duration == 604800) { // 7 days
            return DURATION_7D;
        } else {
            return 0; // Invalid duration
        }
    }

    /**
     * @notice Calculate power for compound multiplier
     * @param base Base number
     * @param exponent Exponent
     * @return result Result of base^exponent
     */
    function _power(uint256 base, uint256 exponent) internal pure returns (uint256 result) {
        result = BASIS_POINTS; // Start with 1 (10000 basis points)
        for (uint256 i = 0; i < exponent; i++) {
            result = (result * base) / BASIS_POINTS;
        }
    }
}

contracts/PredictionInsurance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PredictionInsurance
 * @notice Handles prediction insurance with 10% cost and 50% refund mechanism
 * @dev Users can buy insurance for their predictions to get partial refunds on losses
 */
contract PredictionInsurance is ReentrancyGuard, Pausable, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable ntiqToken;
    address public treasury;

    uint256 public constant INSURANCE_COST_RATE = 1000; // 10% = 1000 basis points
    uint256 public constant REFUND_RATE = 5000; // 50% = 5000 basis points
    uint256 public constant BASIS_POINTS = 10000;

    struct InsurancePolicy {
        address user;
        bytes32 predictionId;
        uint256 stakeAmount;
        uint256 insuranceCost;
        uint256 timestamp;
        bool claimed;
        bool active;
    }

    mapping(bytes32 => InsurancePolicy) public policies;
    mapping(address => uint256) public userTotalInsured;
    uint256 public totalInsuranceCost;
    uint256 public totalRefundsPaid;

    event InsurancePurchased(
        bytes32 indexed policyId,
        bytes32 indexed predictionId,
        address indexed user,
        uint256 stakeAmount,
        uint256 insuranceCost,
        uint256 timestamp
    );

    event InsuranceClaimed(
        bytes32 indexed policyId,
        address indexed user,
        uint256 refundAmount,
        uint256 timestamp
    );

    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(
        address _ntiqToken,
        address _treasury
    ) Ownable(msg.sender) {
        require(_ntiqToken != address(0), "Invalid NTIQ token address");
        require(_treasury != address(0), "Invalid treasury address");

        ntiqToken = IERC20(_ntiqToken);
        treasury = _treasury;
    }

    /**
     * @notice Buy insurance for a prediction
     * @param policyId Unique identifier for the insurance policy
     * @param predictionId Unique identifier for the prediction being insured
     * @param stakeAmount Amount of NTIQ staked in the prediction
     */
    function buyInsurance(
        bytes32 policyId,
        bytes32 predictionId,
        uint256 stakeAmount
    ) external nonReentrant whenNotPaused returns (bool) {
        require(stakeAmount > 0, "Invalid stake amount");
        require(policies[policyId].user == address(0), "Policy already exists");
        require(policies[policyId].active == false, "Policy already active");

        // Calculate insurance cost (10% of stake amount)
        uint256 insuranceCost = (stakeAmount * INSURANCE_COST_RATE) / BASIS_POINTS;

        // Transfer insurance cost from user to contract
        ntiqToken.safeTransferFrom(msg.sender, address(this), insuranceCost);

        // Create insurance policy
        policies[policyId] = InsurancePolicy({
            user: msg.sender,
            predictionId: predictionId,
            stakeAmount: stakeAmount,
            insuranceCost: insuranceCost,
            timestamp: block.timestamp,
            claimed: false,
            active: true
        });

        userTotalInsured[msg.sender] += stakeAmount;
        totalInsuranceCost += insuranceCost;

        emit InsurancePurchased(
            policyId,
            predictionId,
            msg.sender,
            stakeAmount,
            insuranceCost,
            block.timestamp
        );

        return true;
    }

    /**
     * @notice Claim insurance refund (50% of original stake)
     * @param policyId Unique identifier for the insurance policy
     */
    function claimInsurance(
        bytes32 policyId
    ) external nonReentrant whenNotPaused returns (bool) {
        InsurancePolicy storage policy = policies[policyId];

        require(policy.user == msg.sender, "Not policy owner");
        require(policy.active, "Policy not active");
        require(!policy.claimed, "Already claimed");

        // Calculate refund amount (50% of original stake)
        uint256 refundAmount = (policy.stakeAmount * REFUND_RATE) / BASIS_POINTS;

        // Mark as claimed
        policy.claimed = true;
        policy.active = false;

        // Transfer refund to user
        ntiqToken.safeTransfer(msg.sender, refundAmount);

        totalRefundsPaid += refundAmount;

        emit InsuranceClaimed(
            policyId,
            msg.sender,
            refundAmount,
            block.timestamp
        );

        return true;
    }

    /**
     * @notice Update treasury address
     * @param newTreasury New treasury address
     */
    function updateTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Invalid treasury address");
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @notice Withdraw collected insurance costs to treasury
     */
    function withdrawInsuranceCosts() external onlyOwner nonReentrant {
        uint256 balance = ntiqToken.balanceOf(address(this));
        require(balance > 0, "No funds to withdraw");

        ntiqToken.safeTransfer(treasury, balance);
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get insurance policy info
     * @param policyId Unique identifier for the insurance policy
     */
    function getPolicy(bytes32 policyId) external view returns (
        address user,
        bytes32 predictionId,
        uint256 stakeAmount,
        uint256 insuranceCost,
        uint256 timestamp,
        bool claimed,
        bool active
    ) {
        InsurancePolicy memory policy = policies[policyId];
        return (
            policy.user,
            policy.predictionId,
            policy.stakeAmount,
            policy.insuranceCost,
            policy.timestamp,
            policy.claimed,
            policy.active
        );
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalInsuranceCost,
        uint256 _totalRefundsPaid
    ) {
        return (totalInsuranceCost, totalRefundsPaid);
    }
}

contracts/PredictionStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PredictionStaking
 * @notice Handles prediction stakes with accuracy-based reward multipliers
 * @dev Supports multipliers: 0.9x, 1.5x, 2.0x, 3.0x with 4% platform fee on wins
 * @dev Includes duration-based multipliers and oracle integration
 */
contract PredictionStaking is ReentrancyGuard, Pausable, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable ntiqToken;
    address public treasury;
    address public oracle;

    uint256 public constant PLATFORM_FEE_RATE = 400; // 4% = 400 basis points
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MIN_STAKE = 50 ether; // 50 NTIQ
    uint256 public constant MAX_STAKE = 10000 ether; // 10,000 NTIQ

    // Duration multipliers (basis points)
    uint256 public constant DURATION_1H = 12000; // 1.2x
    uint256 public constant DURATION_6H = 15000; // 1.5x
    uint256 public constant DURATION_24H = 20000; // 2.0x
    uint256 public constant DURATION_7D = 30000; // 3.0x

    // Accuracy thresholds (basis points)
    uint256 public constant ACCURACY_99_5 = 9950; // ≥99.5%
    uint256 public constant ACCURACY_98 = 9800;   // ≥98%
    uint256 public constant ACCURACY_95 = 9500;   // ≥95%
    uint256 public constant ACCURACY_90 = 9000;   // ≥90%

    struct PredictionStake {
        address user;
        uint256 amount;
        uint256 timestamp;
        uint256 duration; // Duration in seconds (1h, 6h, 24h, 7d)
        uint256 predictedPrice;
        uint256 actualPrice;
        uint256 accuracy; // Accuracy in basis points
        bool released;
        bool forfeited;
        uint256 rewardAmount;
        uint256 durationMultiplier; // Duration-based multiplier
    }

    mapping(bytes32 => PredictionStake) public stakes;
    mapping(address => uint256) public userTotalStaked;
    uint256 public totalStaked;
    uint256 public totalRewardsDistributed;
    uint256 public totalFeesCollected;

    event StakeLocked(
        bytes32 indexed predictionId,
        address indexed user,
        uint256 amount,
        uint256 timestamp
    );

    event RewardReleased(
        bytes32 indexed predictionId,
        address indexed user,
        uint256 reward,
        uint256 fee,
        uint256 multiplierBasisPoints
    );

    event StakeForfeited(
        bytes32 indexed predictionId,
        address indexed user,
        uint256 amount
    );

    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(
        address _ntiqToken,
        address _treasury,
        address _oracle
    ) Ownable(msg.sender) {
        require(_ntiqToken != address(0), "Invalid NTIQ token address");
        require(_treasury != address(0), "Invalid treasury address");
        require(_oracle != address(0), "Invalid oracle address");

        ntiqToken = IERC20(_ntiqToken);
        treasury = _treasury;
        oracle = _oracle;
    }

    /**
     * @notice Lock NTIQ tokens for a prediction
     * @param predictionId Unique identifier for the prediction
     * @param amount Amount of NTIQ to stake (must be between 50-10,000)
     * @param duration Duration in seconds (3600=1h, 21600=6h, 86400=24h, 604800=7d)
     * @param predictedPrice The predicted price
     */
    function lockStake(
        bytes32 predictionId,
        uint256 amount,
        uint256 duration,
        uint256 predictedPrice
    ) external nonReentrant whenNotPaused returns (bool) {
        require(amount >= MIN_STAKE, "Stake below minimum");
        require(amount <= MAX_STAKE, "Stake above maximum");
        require(stakes[predictionId].user == address(0), "Prediction already staked");
        require(predictedPrice > 0, "Invalid predicted price");

        // Validate duration and get multiplier
        uint256 durationMultiplier = _getDurationMultiplier(duration);
        require(durationMultiplier > 0, "Invalid duration");

        // Transfer NTIQ from user to contract
        ntiqToken.safeTransferFrom(msg.sender, address(this), amount);

        // Store stake info
        stakes[predictionId] = PredictionStake({
            user: msg.sender,
            amount: amount,
            timestamp: block.timestamp,
            duration: duration,
            predictedPrice: predictedPrice,
            actualPrice: 0,
            accuracy: 0,
            released: false,
            forfeited: false,
            rewardAmount: 0,
            durationMultiplier: durationMultiplier
        });

        userTotalStaked[msg.sender] += amount;
        totalStaked += amount;

        emit StakeLocked(predictionId, msg.sender, amount, block.timestamp);

        return true;
    }

    /**
     * @notice Release reward based on actual price and accuracy
     * @param predictionId Unique identifier for the prediction
     * @param actualPrice The actual price at prediction end time
     */
    function releaseReward(
        bytes32 predictionId,
        uint256 actualPrice
    ) external nonReentrant onlyOwner returns (bool) {
        PredictionStake storage stake = stakes[predictionId];

        require(stake.user != address(0), "Prediction not found");
        require(!stake.released, "Reward already released");
        require(!stake.forfeited, "Stake already forfeited");
        require(actualPrice > 0, "Invalid actual price");

        // Update stake with actual price
        stake.actualPrice = actualPrice;

        // Calculate accuracy
        uint256 accuracy = _calculateAccuracy(stake.predictedPrice, actualPrice);
        stake.accuracy = accuracy;

        // Determine multiplier based on accuracy
        uint256 multiplierBasisPoints = _getAccuracyMultiplier(accuracy);

        // Calculate gross reward with duration multiplier
        uint256 baseReward = (stake.amount * multiplierBasisPoints) / BASIS_POINTS;
        uint256 grossReward = (baseReward * stake.durationMultiplier) / BASIS_POINTS;

        uint256 platformFee = 0;
        uint256 netReward = grossReward;

        // Apply 4% platform fee only for winning predictions (1.5x, 2.0x, 3.0x)
        if (multiplierBasisPoints >= 1500) {
            platformFee = (grossReward * PLATFORM_FEE_RATE) / BASIS_POINTS;
            netReward = grossReward - platformFee;
        }

        // Mark as released
        stake.released = true;
        stake.rewardAmount = netReward;

        // Transfer reward to user
        ntiqToken.safeTransfer(stake.user, netReward);

        // Transfer fee to treasury if applicable
        if (platformFee > 0) {
            ntiqToken.safeTransfer(treasury, platformFee);
            totalFeesCollected += platformFee;
        }

        totalRewardsDistributed += netReward;

        emit RewardReleased(
            predictionId,
            stake.user,
            netReward,
            platformFee,
            multiplierBasisPoints
        );

        return true;
    }

    /**
     * @notice Forfeit stake when accuracy < 90%
     * @param predictionId Unique identifier for the prediction
     */
    function forfeitStake(
        bytes32 predictionId
    ) external nonReentrant onlyOwner returns (bool) {
        PredictionStake storage stake = stakes[predictionId];

        require(stake.user != address(0), "Prediction not found");
        require(!stake.released, "Reward already released");
        require(!stake.forfeited, "Stake already forfeited");

        // Mark as forfeited
        stake.forfeited = true;

        // Transfer entire stake to treasury
        ntiqToken.safeTransfer(treasury, stake.amount);
        totalFeesCollected += stake.amount;

        emit StakeForfeited(predictionId, stake.user, stake.amount);

        return true;
    }

    /**
     * @notice Update treasury address
     * @param newTreasury New treasury address
     */
    function updateTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Invalid treasury address");
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get stake info
     * @param predictionId Unique identifier for the prediction
     */
    function getStake(bytes32 predictionId) external view returns (
        address user,
        uint256 amount,
        uint256 timestamp,
        uint256 duration,
        uint256 predictedPrice,
        uint256 actualPrice,
        uint256 accuracy,
        uint256 durationMultiplier,
        bool released,
        bool forfeited,
        uint256 rewardAmount
    ) {
        PredictionStake memory stake = stakes[predictionId];
        return (
            stake.user,
            stake.amount,
            stake.timestamp,
            stake.duration,
            stake.predictedPrice,
            stake.actualPrice,
            stake.accuracy,
            stake.durationMultiplier,
            stake.released,
            stake.forfeited,
            stake.rewardAmount
        );
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalStaked,
        uint256 _totalRewardsDistributed,
        uint256 _totalFeesCollected
    ) {
        return (totalStaked, totalRewardsDistributed, totalFeesCollected);
    }

    /**
     * @notice Update oracle address
     * @param newOracle New oracle address
     */
    function updateOracle(address newOracle) external onlyOwner {
        require(newOracle != address(0), "Invalid oracle address");
        oracle = newOracle;
    }

    /**
     * @notice Get duration multiplier for given duration
     * @param duration Duration in seconds
     * @return multiplier Duration multiplier in basis points
     */
    function _getDurationMultiplier(uint256 duration) internal pure returns (uint256 multiplier) {
        if (duration == 3600) { // 1 hour
            return DURATION_1H;
        } else if (duration == 21600) { // 6 hours
            return DURATION_6H;
        } else if (duration == 86400) { // 24 hours
            return DURATION_24H;
        } else if (duration == 604800) { // 7 days
            return DURATION_7D;
        } else {
            return 0; // Invalid duration
        }
    }

    /**
     * @notice Calculate accuracy between predicted and actual price
     * @param predictedPrice The predicted price
     * @param actualPrice The actual price
     * @return accuracy Accuracy in basis points (10000 = 100%)
     */
    function _calculateAccuracy(uint256 predictedPrice, uint256 actualPrice) internal pure returns (uint256 accuracy) {
        if (actualPrice == 0) return 0;

        uint256 difference = predictedPrice > actualPrice ? 
            predictedPrice - actualPrice : 
            actualPrice - predictedPrice;

        uint256 errorPercentage = (difference * BASIS_POINTS) / actualPrice;
        return BASIS_POINTS - errorPercentage;
    }

    /**
     * @notice Get multiplier based on accuracy
     * @param accuracy Accuracy in basis points
     * @return multiplier Multiplier in basis points
     */
    function _getAccuracyMultiplier(uint256 accuracy) internal pure returns (uint256 multiplier) {
        if (accuracy >= ACCURACY_99_5) {
            return 30000; // 3.0x
        } else if (accuracy >= ACCURACY_98) {
            return 20000; // 2.0x
        } else if (accuracy >= ACCURACY_95) {
            return 15000; // 1.5x
        } else if (accuracy >= ACCURACY_90) {
            return 9000; // 0.9x
        } else {
            return 0; // Forfeit
        }
    }
}

